# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""cumulative_trapezoid: out[..., i, ...] = dx * sum_{k=0..i} (y_k + y_{k+1}) / 2.

Reference semantics reproduced from torch.cumulative_trapezoid (verified on the
target): the reduced axis shrinks by one (max(N-1, 0)) and element 0 is
(y_0 + y_1) * 0.5 * dx, i.e. the inclusive prefix scan of the trapezoid edges.

Layout model: y is viewed as (pre, N, post) with post = prod(shape[dim+1:]) and
the reduced axis having stride `post` (contiguous tensor).  Each program owns
whole "columns" (pre, post) pairs and walks the reduced axis in chunks of B,
keeping one scalar running offset per column.

The prefix inside a chunk is NOT built with tl.cumsum: on this target
hivm.hir.vcumsum is emulated with scalar instructions (~16 cycles/element,
AIV scalar ratio 0.92 in the round-1 profile).  Instead the chunk prefix is
synthesised from generic vector ops: a lower-triangular masked broadcast of the
chunk followed by a reduction (inc[i] = sum_{k<=i} t[k]), which the vector pipe
executes B/64 instructions per element instead of one scalar step per element.
The inter-chunk offset uses a Neumaier-compensated scalar carry.
"""

import torch
import triton
import triton.language as tl

# Ascend launches at most 65535 blocks (coreDim) per kernel.
_MAX_GRID = 65535


@triton.jit
def _cumtrapz_scan_kernel(
    y_ptr,
    out_ptr,
    N,
    post,
    M,
    dx,
    B: tl.constexpr,
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)

    kk = tl.arange(0, B)
    ii = tl.arange(0, B)
    for col in range(pid, M, nprog):
        pre = col // post
        base_in = pre * (N * post) + (col - pre * post)
        base_out = pre * ((N - 1) * post) + (col - pre * post)

        carry = 0.0
        comp = 0.0
        for start in range(0, N - 1, B):
            idx = start + kk
            mask = idx < N - 1
            off = base_in + idx * post
            a = tl.load(y_ptr + off, mask=mask, other=0.0).to(tl.float32)
            b = tl.load(y_ptr + off + post, mask=mask, other=0.0).to(tl.float32)
            t = (a + b) * 0.5
            # inclusive prefix over the chunk: inc[i] = sum_{k<=i} t[k]
            inc = tl.sum(tl.where(kk[:, None] <= ii[None, :], t[:, None], 0.0), axis=0)
            tl.store(out_ptr + base_out + idx * post, (inc + carry) * dx, mask=mask)
            # Neumaier-compensated running offset
            s = tl.sum(t, axis=0)
            fixed = s - comp
            total = carry + fixed
            comp = (total - carry) - fixed
            carry = total


def _chunk(N, post):
    """Chunk length along the reduced axis (the [B, B] prefix tile must fit UB)."""
    b = max(triton.next_power_of_2(N - 1), 16)
    return min(b, 64 if post == 1 else 32)


def cumulative_trapezoid(y, dx=1, dim=-1):
    ndim = y.dim()
    d = dim if dim >= 0 else dim + ndim
    N = y.shape[d]

    sizes = list(y.shape)
    sizes[d] = max(N - 1, 0)
    out_dtype = y.dtype if y.dtype.is_floating_point else torch.get_default_dtype()
    out = torch.empty(sizes, dtype=out_dtype, device=y.device)
    if N <= 1 or out.numel() == 0:
        return out

    post = 1
    for s in y.shape[d + 1 :]:
        post *= s
    M = y.numel() // N

    yc = y if y.is_contiguous() else y.contiguous()
    grid = min(M, _MAX_GRID)
    _cumtrapz_scan_kernel[(grid,)](
        yc,
        out,
        N,
        post,
        M,
        float(dx),
        B=_chunk(N, post),
    )
    return out
